sql.insert:
INSERT INTO photo_variants (
  photo_variant_id, location_id, fragment_index, background_image_path,
  character_image_path, sort_order
) VALUES (
  @photo_variant_id, @location_id, @fragment_index, @background_image_path,
  @character_image_path, @sort_order
)
ON CONFLICT(photo_variant_id) DO UPDATE SET
  location_id = excluded.location_id,
  fragment_index = excluded.fragment_index,
  background_image_path = excluded.background_image_path,
  character_image_path = excluded.character_image_path,
  sort_order = excluded.sort_order;
